import random
RSc=random.Random(8)
EL=[("الهيدروجين","H"),("الهيليوم","He"),("الكربون","C"),("النيتروجين","N"),("الأكسجين","O"),("الصوديوم","Na"),("المغنيسيوم","Mg"),("الألومنيوم","Al"),("السيليكون","Si"),("الفوسفور","P"),
("الكبريت","S"),("الكلور","Cl"),("البوتاسيوم","K"),("الكالسيوم","Ca"),("الحديد","Fe"),("النحاس","Cu"),("الزنك","Zn"),("الفضة","Ag"),("الذهب","Au"),("الزئبق","Hg"),("الرصاص","Pb"),("القصدير","Sn"),("اليورانيوم","U"),("النيون","Ne"),("الليثيوم","Li"),("اليود","I"),("البلاتين","Pt"),("الفلور","F")]
PLAN=["عطارد","الزهرة","الأرض","المريخ","المشتري","زحل","أورانوس","نبتون"]
def sci_qs():
    out=[]; syms=[s for _,s in EL]; names=[n for n,_ in EL]
    def o(a,pool):
        c=[x for x in pool if x!=a]; RSc.shuffle(c); return [a]+c[:3]
    for n,s in EL:
        out.append((f"ما الرمز الكيميائي لعنصر {n}؟",o(s,syms)))
        out.append((f"أي عنصر رمزه الكيميائي {s}؟",o(n,names)))
    for i,p in enumerate(PLAN):
        out.append((f"ما ترتيب كوكب {p} من حيث القرب من الشمس؟",o(str(i+1),[str(x) for x in range(1,9)])))
    out+=[("ما أكبر كواكب المجموعة الشمسية؟",o("المشتري",PLAN)),("ما أقرب كوكب إلى الشمس؟",o("عطارد",PLAN)),("ما الكوكب المعروف بحلقاته الواضحة؟",o("زحل",PLAN)),
    ("ما الكوكب الذي يُلقّب بالكوكب الأحمر؟",o("المريخ",PLAN)),("ما أسخن كواكب المجموعة الشمسية؟",o("الزهرة",PLAN)),("ما أبعد كوكب عن الشمس في المجموعة الشمسية؟",o("نبتون",PLAN)),
    ("كم عدد كواكب المجموعة الشمسية؟",["8","9","7","10"]),("كم عظمة في جسم الإنسان البالغ تقريباً؟",["206","300","180","250"]),("كم حجرة في قلب الإنسان؟",["4","2","3","5"]),
    ("ما أكبر عضو في جسم الإنسان؟",o("الجلد",["الكبد","الرئة","القلب","الدماغ","المعدة"])),("ما أكبر عضو داخلي في جسم الإنسان؟",o("الكبد",["الرئة","القلب","الدماغ","المعدة","الكلية"])),
    ("ما العضو المسؤول عن ضخ الدم في الجسم؟",o("القلب",["الكبد","الرئة","الدماغ","الكلية"])),("ما الغاز الذي يحتاجه الإنسان للتنفس؟",o("الأكسجين",["النيتروجين","الهيليوم","الأرجون","الهيدروجين"])),
    ("ما الغاز الذي تمتصه النباتات في عملية البناء الضوئي؟",o("ثاني أكسيد الكربون",["أول أكسيد الكربون","كبريتيد الهيدروجين","ثاني أكسيد النيتروجين"])),
    ("ما الصبغة الخضراء في أوراق النباتات؟",o("الكلوروفيل",["الهيموغلوبين","الميلانين","الكيراتين","الكولاجين"])),("ما المادة التي تنقل الأكسجين في الدم؟",o("الهيموغلوبين",["الكلوروفيل","الميلانين","الأنسولين","الكيراتين"])),
    ("ما الهرمون الذي ينظم سكر الدم؟",o("الأنسولين",["الأدرينالين","الثيروكسين","الكورتيزول","الميلاتونين"])),("ما الهرمون الذي ينظم النوم؟",o("الميلاتونين",["الأنسولين","الأدرينالين","الثيروكسين","الكورتيزول"])),
    ("ما درجة غليان الماء عند مستوى سطح البحر بالدرجة المئوية؟",["100","90","80","120"]),("ما درجة تجمد الماء بالدرجة المئوية؟",["0","10","-10","4"]),
    ("ما سرعة الضوء في الفراغ تقريباً بالكيلومتر في الثانية؟",["300 ألف","150 ألف","30 ألف","3 ملايين"]),("من صاحب نظرية النسبية؟",o("أينشتاين",["نيوتن","غاليليو","داروين","بور"])),
    ("من صاحب قانون الجاذبية العامة؟",o("نيوتن",["أينشتاين","غاليليو","داروين","كبلر"])),("ما الوحدة التي تُقاس بها القوة؟",o("النيوتن",["الواط","الجول","الأمبير","الفولت"])),
    ("ما الوحدة التي تُقاس بها الطاقة؟",o("الجول",["الواط","النيوتن","الأمبير","الفولت"])),("ما الوحدة التي تُقاس بها شدة التيار الكهربائي؟",o("الأمبير",["الواط","النيوتن","الجول","الفولت"])),
    ("ما الوحدة التي تُقاس بها القدرة؟",o("الواط",["الأمبير","النيوتن","الجول","الفولت"])),("ما الرقم الهيدروجيني pH للماء النقي؟",["7","0","14","5"]),
    ("ما أصغر وحدة بنائية في الكائن الحي؟",o("الخلية",["النسيج","العضو","الجهاز","الذرة"])),("ما الجزء من الخلية الذي يحتوي على المادة الوراثية؟",o("النواة",["الغشاء","السيتوبلازم","الميتوكوندريا","الريبوسوم"])),
    ("ما الجزء الذي يُعرف بمحطة الطاقة في الخلية؟",o("الميتوكوندريا",["النواة","الغشاء","السيتوبلازم","الريبوسوم"])),("ما اسم الجزيء الذي يحمل الصفات الوراثية؟",o("DNA",["ATP","RNA","CO2","H2O"])),
    ("ما أقرب نجم إلى الأرض؟",o("الشمس",["سيريوس","فيغا","رجل القنطور","منكب الجوزاء"])),("ما القمر الطبيعي الوحيد للأرض؟",["القمر","فوبوس","تيتان","أوروبا"]),
    ("كم يوماً تقريباً تستغرق الأرض للدوران حول الشمس؟",["365","360","300","400"]),("كم ساعة تقريباً تستغرق الأرض لتدور حول نفسها؟",["24","12","36","48"]),
    ]
    return out
